265	static ka_pte_t *ka_mm_inner_pte_offset_map(ka_pmd_t *pmd, unsigned long addr, ka_pmd_t *pmdvalp)
266	{
267	    ka_pmd_t pmdval;
268	
269	    /* rcu_read_lock() to be added later */
270	    pmdval = ka_mm_pmdp_get_lockless(pmd);
271	    if (pmdvalp) {
272	        *pmdvalp = pmdval;
273	    }
274	    if (unlikely(ka_mm_pmd_none(pmdval) || ka_mm_is_pmd_migration_entry(pmdval))) {
275	        goto nomap;
276	    }
277	    if (unlikely(ka_mm_pmd_trans_huge(pmdval) || ka_mm_pmd_devmap(pmdval))) {
278	        goto nomap;
279	    }
280	    if (unlikely(ka_mm_pmd_bad(pmdval))) {
281	        ka_mm_pmd_ERROR(*pmd);
282	        ka_mm_pmd_clear(pmd);
283	        goto nomap;
284	    }
285	    return __ka_mm_pte_map(&pmdval, addr);
286	
287	nomap:
288	    /* rcu_read_unlock() to be added later */
289	    return NULL;
290	}
