293	/**
294	 * @brief get the page table entry of the va
295	 * @attention
296	 * kpg_size=KA_MM_PAGE_SIZE(4K) -> pte
297	 * kpg_size=KA_HPAGE_SIZE(2M) -> pmd
298	 * kpg_size=PUD_SIZE(1G) -> pud
299	 * @param [in] vma: ka_vm_area_struct_t
300	 * @param [in] va: va
301	 * @param [out] kpg_size: real page size from kernel
302	 * @return NULL for fail, others for success, means pte pointer
303	 */
304	void *ka_mm_get_pte(const ka_vm_area_struct_t *vma, u64 va, u64 *kpg_size)
305	{
306	    ka_pgd_t *pgd = NULL;
307	#if LINUX_VERSION_CODE >= KERNEL_VERSION(4, 11, 0)
308	    p4d_t *p4d = NULL;
309	#endif
310	    ka_pud_t *pud = NULL;
311	    ka_pmd_t *pmd = NULL;
312	    ka_pte_t *pte = NULL;
313	
314	    if ((vma == NULL) || (vma->vm_mm == NULL) || (kpg_size == NULL)) {
315	        return NULL;
316	    }
317	    /* too much log, not print */
318	    pgd = ka_mm_pgd_offset(vma->vm_mm, va);
319	    if (PXD_JUDGE(pgd) != 0) {
320	        return NULL;
321	    }
322	
323	#if LINUX_VERSION_CODE >= KERNEL_VERSION(4, 11, 0)
324	    p4d = ka_mm_p4d_offset(pgd, va);
325	    if (PXD_JUDGE(p4d) != 0) {
326	        return NULL;
327	    }
328	
329	    /* if kernel version is above 4.11.0,then 5 level pt arrived.
330	    pud_offset(pgd,va) changed to pud_offset(p4d,va) for x86
331	    but not changed in arm64 */
332	    pud = ka_mm_pud_offset(p4d, va);
333	#else
334	    pud = ka_mm_pud_offset(pgd, va);
335	#endif
336	    if (PUD_GIANT(pud) != 0) {
337	        *kpg_size = KA_MM_GIANT_PAGE_SIZE;
338	        return pud;
339	    }
340	    if (PXD_JUDGE(pud) != 0) {
341	        return NULL;
342	    }
343	
344	    pmd = ka_mm_pmd_offset(pud, va);
345	    /* huge page pmd can not judge bad flag */
346	    if (PMD_HUGE(pmd) != 0) {
347	        *kpg_size = KA_HPAGE_SIZE;
348	        return pmd;
349	    }
350	    if (PMD_JUDGE(pmd) != 0) {
351	        return NULL;
352	    }
353	
354	#if LINUX_VERSION_CODE >= KERNEL_VERSION(6, 5, 0)
355	    pte = ka_mm_inner_pte_offset_map(pmd, va, NULL);
356	#else
357	    pte = ka_mm_pte_offset_map(pmd, va);
358	#endif
359	    if ((pte == NULL) || (ka_mm_pte_none(*pte) != 0) || (ka_mm_pte_present(*pte) == 0)) {
360	        return NULL;
361	    }
362	    *kpg_size = KA_MM_PAGE_SIZE;
363	    return pte;
364	}
365	EXPORT_SYMBOL_GPL(ka_mm_get_pte);
