367	ka_pmd_t *ka_mm_get_va_to_pmd(const ka_vm_area_struct_t *vma, unsigned long va) /* To be deleted */
368	{
369	    ka_pgd_t *pgd = NULL;
370	#if LINUX_VERSION_CODE >= KERNEL_VERSION(4, 11, 0)
371	    p4d_t *p4d = NULL;
372	#endif
373	    ka_pud_t *pud = NULL;
