386	    p4d = ka_mm_p4d_offset(pgd, va);
387	    if (PXD_JUDGE(p4d) != 0) {
388	        return NULL;
389	    }
390	
391	    /* if kernel version is above 4.11.0,then 5 level pt arrived.
392	    pud_offset(pgd,va) changed to pud_offset(p4d,va) for x86
393	    but not changed in arm64 */
394	    pud = ka_mm_pud_offset(p4d, va);
395	    if (PXD_JUDGE(pud) != 0) {
396	        return NULL;
397	    }
398	#else
399	    pud = ka_mm_pud_offset(pgd, va);
400	    if (PXD_JUDGE(pud) != 0) {
401	        return NULL;
402	    }
403	#endif
404	
405	    pmd = ka_mm_pmd_offset(pud, va);
406	    return pmd;
407	}
408	EXPORT_SYMBOL_GPL(ka_mm_get_va_to_pmd);
409	
410	static int ka_mm_va_to_pa_pmd_range(ka_pmd_t *pmd, u64 start, u64 end, u64 *pas, u64 *num)
411	{
412	    ka_pte_t *pte = NULL;
413	    u64 got_num = 0;
414	    u64 va = start;
415	
416	#if LINUX_VERSION_CODE >= KERNEL_VERSION(6, 5, 0)
417	    pte = ka_mm_inner_pte_offset_map(pmd, va, NULL);
418	#else
419	    pte = ka_mm_pte_offset_map(pmd, va);
420	#endif
421	
422	    for (; va != end; pte++, va += KA_MM_PAGE_SIZE) {
423	        if ((ka_mm_pte_none(*pte) != 0) || (ka_mm_pte_present(*pte) == 0)) {
424	            return -ERANGE;
425	        }
426	
427	        pas[got_num] = KA_MM_PFN_PHYS(ka_mm_pte_pfn(*pte));
428	        got_num++;
429	    }
430	
431	    *num = got_num;
432	    return 0;
433	}
434	
435	static int ka_mm_va_to_pa_pud_range(ka_pud_t *pud, u64 start, u64 end, u64 *pas, u64 *num)
436	{
437	    ka_pmd_t *pmd = NULL;
438	    u64 got_num = 0;
439	    u64 va = start;
440	    u64 next;
441	
442	    pmd = ka_mm_pmd_offset(pud, va);
443	    for (; va != end; pmd++, va = next) {
444	        int ret;
445	        u64 n;
446	
447	        if (PXD_JUDGE(pmd) != 0) {
448	            return -EDOM;
449	        }
450	
451	        next = ka_mm_pmd_addr_end(va, end);
452	        ret = ka_mm_va_to_pa_pmd_range(pmd, va, next, &pas[got_num], &n);
453	        if (ret != 0) {
454	            return ret;
455	        }
456	        got_num += n;
457	    }
458	
459	    *num = got_num;
460	    return 0;
461	}
462	
463	#if LINUX_VERSION_CODE >= KERNEL_VERSION(4, 11, 0)
464	static int ka_mm_va_to_pa_p4d_range(p4d_t *p4d, u64 start, u64 end, u64 *pas, u64 *num)
465	{
466	    ka_pud_t *pud = NULL;
467	    u64 got_num = 0;
468	    u64 va = start;
469	    u64 next;
470	
471	    pud = ka_mm_pud_offset(p4d, va);
472	    for (; va != end; pud++, va = next) {
473	        int ret;
474	        u64 n = 0;
475	
476	        if (PXD_JUDGE(pud) != 0) {
477	            return -EDOM;
478	        }
479	
480	        next = pud_addr_end(va, end);
481	        ret = ka_mm_va_to_pa_pud_range(pud, va, next, &pas[got_num], &n);
482	        if (ret != 0) {
483	            return ret;
484	        }
485	        got_num += n;
486	    }
487	
488	    *num = got_num;
489	    return 0;
490	}
