495	    u64 got_num = 0;
496	    u64 va = start;
497	    u64 next;
498	
499	    if (pgd == NULL || pas == NULL || num == NULL) {
500	        return -EINVAL;
501	    }
502	    p4d = ka_mm_p4d_offset(pgd, va);
503	    for (; va != end; p4d++, va = next) {
504	        int ret;
505	        u64 n;
506	
507	        if (PXD_JUDGE(p4d) != 0) {
508	            return -EDOM;
509	        }
510	
511	        next = p4d_addr_end(va, end);
512	        ret = ka_mm_va_to_pa_p4d_range(p4d, va, next, &pas[got_num], &n);
513	        if (ret != 0) {
514	            return ret;
515	        }
516	        got_num += n;
517	    }
518	
519	    *num = got_num;
520	    return 0;
521	}
522	#else
523	int ka_mm_va_to_pa_pgd_range(ka_pgd_t *pgd, u64 start, u64 end, u64 *pas, u64 *num)
524	{
