575	static struct range_rbtree g_ka_ram_record_tree;
576	static KA_TASK_DEFINE_RWLOCK(g_ka_ram_record_lock);
577	
578	static int ka_ram_record_walk_cb(struct resource *res, void *arg)
579	{
580	    struct range_rbtree *tree = (struct range_rbtree *)arg;
581	    struct range_rbtree_node *node = NULL;
582	
583	    node = ka_mm_kzalloc(sizeof(struct range_rbtree_node), KA_GFP_KERNEL | __KA_GFP_ACCOUNT);
584	    if (node == NULL) {
585	        return -ENOMEM;
586	    }
587	
588	    node->start = res->start;
589	    node->size = res->end - res->start + 1;
590	
591	    /* call ka_ram_record_walk_cb when insmod ko, so not need lock */
592	    if (range_rbtree_insert(tree, node) != 0) {
593	        ka_mm_kfree(node);
594	        node = NULL;
595	    }
596	
597	    return 0;
598	}
599	
600	int ka_mm_ram_record_init(void)
601	{
602	    int ret;
603	
604	    range_rbtree_init(&g_ka_ram_record_tree);
605	
606	    ret = walk_iomem_res_desc(IORES_DESC_NONE, IORESOURCE_SYSTEM_RAM | IORESOURCE_BUSY, 0, ULLONG_MAX,
607	                              &g_ka_ram_record_tree, ka_ram_record_walk_cb);
608	    if ((ret != 0) && (ret != -ENOMEM)) {
609	        ka_mm_ram_record_uninit();
610	        return ret;
611	    }
612	
613	    ka_info("Ram walk finish, ret=%d, node_num=%u\n", ret, g_ka_ram_record_tree.node_num);
614	    return 0;
615	}
616	
617	void ka_mm_ram_record_uninit(void)
618	{
619	    struct range_rbtree_node *node = NULL;
620	
621	    do {
622	        ka_task_write_lock(&g_ka_ram_record_lock);
623	        node = range_rbtree_erase_one(&g_ka_ram_record_tree);
624	        ka_task_write_unlock(&g_ka_ram_record_lock);
625	
626	        if (node == NULL) {
627	            break;
628	        }
629	        ka_mm_kfree(node);
630	    } while (node != NULL);
631	}
632	
633	/* use read_lock, could not call in interrupt */
634	bool ka_mm_mem_is_ram(u64 pa)
635	{
636	    bool is_ram;
637	
638	    ka_task_read_lock(&g_ka_ram_record_lock);
639	    is_ram = range_rbtree_check_exist(&g_ka_ram_record_tree, pa, 1);
640	    ka_task_read_unlock(&g_ka_ram_record_lock);
641	
642	    if (!is_ram) {
643	        is_ram = page_is_ram(KA_MM_PFN_DOWN(pa));
644	    }
645	
646	    return is_ram;
647	}
648	EXPORT_SYMBOL_GPL(ka_mm_mem_is_ram);
