366	    for (node = rb_first(&from->rbroot); node; node = rb_next(node)) {
367	        iova = rb_entry(node, struct iova, node);
368	
369	        if (iova->pfn_lo == IOVA_ANCHOR) {
370	            continue;
371	        }
372	
373	        new_iova = reserve_iova(to, iova->pfn_lo, iova->pfn_hi);
374	        if (IS_ERR_OR_NULL(new_iova)) {
375	            printk(KERN_ERR "Reserve iova range %lx@%lx failed\n", iova->pfn_lo, iova->pfn_hi);
376	        }
377	    }
378	    spin_unlock_irqrestore(&from->iova_rbtree_lock, flags);
379	#else
380	    copy_reserved_iova(from, to);
381	#endif
382	}
383	EXPORT_SYMBOL_GPL(ka_copy_reserved_iova);
