541	int ka_mdev_register_type_ops(ka_device_t *parent_dev, const ka_mdev_type_ops *ops)
542	{
543	    ka_mdev_ops_node *node = NULL;
544	
545	    if (parent_dev == NULL || ops == NULL) {
546	        return -EINVAL;
547	    }
548	    mutex_lock(&ka_mdev_ops_lock);
549	    list_for_each_entry(node, &ka_mdev_ops_list, list)
550	    {
551	        if (node->dev == parent_dev) {
552	            mutex_unlock(&ka_mdev_ops_lock);
553	            return -EEXIST;
554	        }
555	    }
556	    node = kzalloc(sizeof(ka_mdev_ops_node), GFP_KERNEL);
557	    if (node == NULL) {
558	        mutex_unlock(&ka_mdev_ops_lock);
559	        return -ENOMEM;
560	    }
561	    node->dev = parent_dev;
562	    node->ops = ops;
563	    list_add(&node->list, &ka_mdev_ops_list);
564	    mutex_unlock(&ka_mdev_ops_lock);
565	
566	    return 0;
567	}
568	EXPORT_SYMBOL_GPL(ka_mdev_register_type_ops);
569	
570	void ka_mdev_unregister_type_ops(ka_device_t *parent_dev)
571	{
572	    ka_mdev_ops_node *node = NULL, *tmp = NULL;
573	
574	    mutex_lock(&ka_mdev_ops_lock);
575	    list_for_each_entry_safe(node, tmp, &ka_mdev_ops_list, list)
576	    {
577	        if (node->dev == parent_dev) {
578	            list_del(&node->list);
579	            kfree(node);
580	            break;
581	        }
582	    }
583	    mutex_unlock(&ka_mdev_ops_lock);
584	}
585	EXPORT_SYMBOL_GPL(ka_mdev_unregister_type_ops);
