587	static const ka_mdev_type_ops *ka_mdev_get_ops(ka_device_t *parent_dev)
588	{
589	    ka_mdev_ops_node *node = NULL;
590	    const ka_mdev_type_ops *ops = NULL;
591	
592	    if (unlikely(parent_dev == NULL)) {
593	        return NULL;
594	    }
595	    mutex_lock(&ka_mdev_ops_lock);
596	    list_for_each_entry(node, &ka_mdev_ops_list, list)
597	    {
598	        if (node->dev == parent_dev) {
599	            ops = node->ops;
600	            break;
