800	{
801	    int ret = 0;
802	#if ((LINUX_VERSION_CODE < KERNEL_VERSION(6, 0, 0)))
803	    unsigned long events = VFIO_IOMMU_NOTIFY_DMA_UNMAP;
804	
805	    vdev->iommu_notifier.notifier_call = ka_hw_vdev_iommu_notifier;
806	    vdev->group_notifier.notifier_call = ka_hw_vdev_group_notifier;
807	    ret = vfio_register_notifier(mdev_dev(vdev->mdev), VFIO_IOMMU_NOTIFY, &events, &vdev->iommu_notifier);
808	    if (ret != 0) {
809	        goto out;
810	    }
811	    events = VFIO_GROUP_NOTIFY_SET_KVM;
812	    ret = vfio_register_notifier(mdev_dev(vdev->mdev), VFIO_GROUP_NOTIFY, &events, &vdev->group_notifier);
813	    if (ret != 0) {
814	        goto unregister_iommu;
815	    }
816	
817	    ret = ka_hw_get_vfio_group(vdev);
818	    if (ret != 0) {
819	        goto unregister_group;
820	    }
821	
822	    return 0;
823	
824	unregister_group:
825	    vfio_unregister_notifier(mdev_dev(vdev->mdev), VFIO_GROUP_NOTIFY, &vdev->group_notifier);
826	unregister_iommu:
827	    vfio_unregister_notifier(mdev_dev(vdev->mdev), VFIO_IOMMU_NOTIFY, &vdev->iommu_notifier);
828	    vdev->iommu_notifier.notifier_call = NULL;
829	    vdev->group_notifier.notifier_call = NULL;
830	out:
831	#endif
832	    return ret;
833	}
