static void guid_to_uuid(ka_device_t *dev, uuid_le *dst, const guid_t *src)
{
    if (UUID_SIZE != sizeof(guid_t) || UUID_SIZE != sizeof(uuid_le) || UUID_SIZE != sizeof(uuid_t)) {
