#if IS_ENABLED(CONFIG_VFIO)
#if KA_IS_ASCEND_HOST_KERNEL
    struct ka_hw_vfio_vdev *vfio_vdev = NULL;

    vfio_vdev = vfio_alloc_device(ka_hw_vfio_vdev, vfio_dev, &mdev->dev, &ka_hw_vnpu_vfio_dev_ops);
    if (IS_ERR(vfio_vdev)) {
